import { html } from 'lit';
import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';
import defaultArgs from './previews/default.data.json';

const squiz = squizStoryRenderer(comp.main);

export default {
  title: 'dxp components/Anchor Navigation',
};

function mockInfoFor(sidebarItems = ['anchor_nav']) {
  return squizInfoMock({
    ctx: { assetId: '5001' },
    env: {MATRIX_API_IDENTIFIER: 'mock'},
    mock: {
      resolveUri: () => ({
        ok: true,
        data: {
          metadata: {
            sidebar_items: sidebarItems,
          },
        },
      }),
    },
  });
}

function renderStory(args, info) {
  requestAnimationFrame(() => {
    window.__ntgds__?.run?.('anchor-nav');
  });
  return html`
    <article class="content-area">
      ${squiz(args, info)}
      <p>This preview simulates a content page with multiple section headings.</p>
      <h2>Getting started</h2>
      <p>Introductory guidance for the first section.</p>
      <h2>What you need</h2>
      <p>Checklist content for the second section.</p>
      <h2>Next steps</h2>
      <p>Follow-up content for the final section.</p>
    </article>
  `;
}

const defaultInfo = mockInfoFor();

export const Default = {
  render: (args) => renderStory(args, defaultInfo),
  args: defaultArgs,
  argTypes: {
    title: { control: 'text' },
    hn: { control: 'text' },
    area: { control: 'text' },
  },
  parameters: {
    docs: {
      description: {
        story: 'A page opted into `anchor_nav` renders an in-page navigation list from the h2 headings inside `.content-area`.',
      },
    },
  },
};

const disabledInfo = mockInfoFor(['sidebar_nav']);

export const NotOptedIn = {
  render: () => renderStory(defaultArgs, disabledInfo),
  parameters: {
    docs: {
      description: {
        story: 'When `sidebar_items` does not include `anchor_nav`, the component emits nothing and the page content renders without the in-page navigation block.',
      },
    },
  },
};